/* Updated gt06.js - Complete protocol handler */
f = require('../functions');
const crc = require('crc');

exports.protocol = 'GT06N';
exports.model_name = 'GT06N';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;
  this.server_time_offset = 0;

  // Helper function to convert hex string to buffer
  this.hexStringToBuffer = function(hexString) {
    return Buffer.from(hexString, 'hex');
  };

  this.parse_data = function (data) {
    var hexData = this.bufferToHexString(data);
    var parts = {
      'raw': hexData,
      'start': hexData.substr(0, 4)
    };

    if (parts['start'] != '7878' && parts['start'] != '7979') {
      console.log('Invalid start bytes:', parts['start']);
      parts.cmd = 'invalid';
      parts.action = 'noop';
      return parts;
    }

    parts['length'] = parseInt(hexData.substr(4, 2), 16);
    parts['protocol_id'] = hexData.substr(6, 2);
    parts['information'] = hexData.substr(8, parts['length'] * 2 - 4);
    parts['serial_number'] = hexData.substr(8 + parts['length'] * 2 - 4, 4);
    parts['error_check'] = hexData.substr(8 + parts['length'] * 2, 2);
    parts['finish'] = hexData.substr(10 + parts['length'] * 2, 4);

    // Validate CRC
    var crcData = hexData.substr(4, parts['length'] * 2);
    var calculatedCRC = this.calculateCRC(crcData);
    if (parts['error_check'] != calculatedCRC) {
      console.log('CRC mismatch:', parts['error_check'], '!=', calculatedCRC);
      parts.cmd = 'crc_error';
      parts.action = 'noop';
      return parts;
    }

    // Parse based on protocol ID
    switch(parts['protocol_id']) {
      case '01': // Login packet
        parts['device_id'] = parts['information'].substr(0, 16);
        parts['terminal_info'] = {
          'type': parts['information'].substr(16, 2),
          'timezone': parts['information'].substr(18, 4)
        };
        parts.cmd = 'login_request';
        parts.action = 'login_request';
        break;
        
      case '12': // GPS location data
      case '22': // GPS with address
        parts['data'] = parts['information'];
        parts.cmd = 'location_data';
        parts.action = 'location_data';
        break;
        
      case '13': // Heartbeat
        parts['status_info'] = parts['information'];
        parts.cmd = 'heartbeat';
        parts.action = 'heartbeat';
        break;
        
      case '15': // Command response
        parts['response'] = parts['information'];
        parts.cmd = 'command_response';
        parts.action = 'command_response';
        break;
        
      case '16': // Alarm data
      case '26': // Alarm with address
        parts['data'] = parts['information'];
        parts.cmd = 'alarm';
        parts.action = 'alarm';
        break;
        
      case '17': // LBS location
        parts['data'] = parts['information'];
        parts.cmd = 'lbs_location';
        parts.action = 'lbs_location';
        break;
        
      case '18': // Status information
        parts['status_data'] = parts['information'];
        parts.cmd = 'status_info';
        parts.action = 'status_info';
        break;
        
      case '19': // String information
        parts['string_data'] = parts['information'];
        parts.cmd = 'string_info';
        parts.action = 'string_info';
        break;
        
      case '1a': // GPS multiple data
        parts['multi_data'] = parts['information'];
        parts.cmd = 'gps_multi';
        parts.action = 'gps_multi';
        break;
        
      case '80': // Command to upload LBS
        parts['command_data'] = parts['information'];
        parts.cmd = 'upload_lbs';
        parts.action = 'upload_lbs';
        break;
        
      default:
        parts.cmd = 'unknown';
        parts.action = 'noop';
        console.log('Unknown protocol:', parts['protocol_id']);
    }

    return parts;
  };

  // Calculate CRC checksum
  this.calculateCRC = function(hexData) {
    var bytes = [];
    for (var i = 0; i < hexData.length; i += 2) {
      bytes.push(parseInt(hexData.substr(i, 2), 16));
    }
    
    var crc = 0;
    for (var i = 0; i < bytes.length; i++) {
      crc ^= bytes[i];
      for (var j = 0; j < 8; j++) {
        if (crc & 0x0001) {
          crc = (crc >> 1) ^ 0xA001;
        } else {
          crc = crc >> 1;
        }
      }
    }
    
    return ((crc & 0xFF) << 8 | (crc >> 8)).toString(16).padStart(4, '0').substr(0, 2);
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  // Response handlers
  this.authorize = function (msg_parts) {
    var serial = msg_parts.serial_number;
    var response = '78780501' + serial + this.calculateCRC('0501' + serial) + '0d0a';
    this.device.send(this.hexStringToBuffer(response));
  };

  this.receive_heartbeat = function (msg_parts) {
    var serial = msg_parts.serial_number;
    var response = '78780513' + serial + this.calculateCRC('0513' + serial) + '0d0a';
    this.device.send(this.hexStringToBuffer(response));
  };

  this.receive_location = function (msg_parts) {
    var serial = msg_parts.serial_number;
    var response = '78780512' + serial + this.calculateCRC('0512' + serial) + '0d0a';
    this.device.send(this.hexStringToBuffer(response));
  };

  this.receive_alarm = function (msg_parts) {
    var str = msg_parts.data;
    
    var data = {
      'protocol': msg_parts.protocol_id,
      'date': this.parseDateTime(str.substr(0, 12)),
      'satellites': parseInt(str.substr(12, 2), 16),
      'latitude_raw': str.substr(14, 8),
      'longitude_raw': str.substr(22, 8),
      'latitude': this.hexToDecimalDegrees(str.substr(14, 8)),
      'longitude': this.hexToDecimalDegrees(str.substr(22, 8)),
      'speed': parseInt(str.substr(30, 2), 16),
      'course': parseInt(str.substr(32, 4), 16),
      'timestamp': new Date(),
      'device_status': f.str_pad(parseInt(str.substr(36, 2), 16).toString(2), 8, 0),
      'lbs': str.substr(38, 16),
      'alarm_type': this.getAlarmType(str.substr(54, 2)),
      'language': str.substr(56, 2),
      'raw_data': str
    };
    
    // Parse status bits
    data['power_status'] = data['device_status'][0]; // 0: normal, 1: low
    data['gps_status'] = data['device_status'][1];   // 0: valid, 1: invalid
    data['charge_status'] = data['device_status'][5]; // 0: not charging, 1: charging
    data['acc_status'] = data['device_status'][6];   // 0: off, 1: on
    data['armed_status'] = data['device_status'][7]; // 0: disarmed, 1: armed
    
    return data;
  };

  this.get_location_data = function (msg_parts) {
    var str = msg_parts.data;
    
    var data = {
      'protocol': msg_parts.protocol_id,
      'date': this.parseDateTime(str.substr(0, 12)),
      'satellites': parseInt(str.substr(12, 2), 16),
      'latitude_raw': str.substr(14, 8),
      'longitude_raw': str.substr(22, 8),
      'latitude': this.hexToDecimalDegrees(str.substr(14, 8)),
      'longitude': this.hexToDecimalDegrees(str.substr(22, 8)),
      'speed': parseInt(str.substr(30, 2), 16),
      'course': parseInt(str.substr(32, 4), 16),
      'device_status': f.str_pad(parseInt(str.substr(36, 2), 16).toString(2), 8, 0),
      'lbs': str.substr(38, 16),
      'raw_data': str
    };
    
    // Parse status bits
    data['power_status'] = data['device_status'][0];
    data['gps_status'] = data['device_status'][1];
    data['charge_status'] = data['device_status'][5];
    data['acc_status'] = data['device_status'][6];
    data['armed_status'] = data['device_status'][7];
    
    return data;
  };

  this.get_status_info = function (msg_parts) {
    var str = msg_parts.status_data;
    
    var data = {
      'protocol': msg_parts.protocol_id,
      'terminal_info': str.substr(0, 8),
      'voltage_level': parseInt(str.substr(8, 2), 16),
      'gsm_signal': parseInt(str.substr(10, 2), 16),
      'alarm_zone': str.substr(12, 4),
      'language': str.substr(16, 2)
    };
    
    return data;
  };

  this.hexToDecimalDegrees = function (hex) {
    var decimal = parseInt(hex, 16);
    return decimal / 1800000;
  };

  this.parseDateTime = function (hexDateTime) {
    var year = parseInt(hexDateTime.substr(0, 2), 16) + 2000;
    var month = parseInt(hexDateTime.substr(2, 2), 16) - 1; // JS months are 0-indexed
    var day = parseInt(hexDateTime.substr(4, 2), 16);
    var hour = parseInt(hexDateTime.substr(6, 2), 16);
    var minute = parseInt(hexDateTime.substr(8, 2), 16);
    var second = parseInt(hexDateTime.substr(10, 2), 16);
    
    return new Date(year, month, day, hour, minute, second);
  };

  this.getAlarmType = function (hexCode) {
    var codes = {
      '01': 'SOS',
      '02': 'Low Battery',
      '03': 'Power Cut',
      '04': 'Shock',
      '05': 'Fence In',
      '06': 'Fence Out',
      '09': 'Over Speed',
      '10': 'Movement',
      '12': 'Enter Area',
      '13': 'Exit Area',
      '15': 'Power On',
      '16': 'GPS First Fix',
      '17': 'GPS Antenna Short',
      '18': 'GPS Antenna Open',
      '19': 'Power Off',
      '20': 'Sleep Mode',
      '21': 'Wake Up',
      '22': 'Door Open',
      '23': 'Door Close'
    };
    
    return codes[hexCode] || 'Unknown Alarm: ' + hexCode;
  };

  // Send commands to device
  this.sendCommand = function (command, params) {
    var commandMap = {
      'set_refresh_time': '8100',
      'set_speed_alarm': '8106',
      'set_fence': '8108',
      'cut_power': '8201',
      'restore_power': '8202',
      'set_relay': '8203',
      'set_odo': '8205'
    };
    
    var cmdHex = commandMap[command] || '8000';
    var buffer = this.buildCommandPacket(cmdHex, params);
    this.device.send(buffer);
  };

  this.buildCommandPacket = function (cmdHex, params) {
    // Implementation for building command packets
    // This is a simplified version
    var serial = f.str_pad(this.__count.toString(16), 4, '0');
    this.__count++;
    
    // Build command string based on command type
    var data = cmdHex + params;
    var length = (data.length / 2 + 2).toString(16).padStart(2, '0');
    
    var packet = '7878' + length + data + serial;
    var crcVal = this.calculateCRC(length + data + serial);
    packet += crcVal + '0d0a';
    
    return this.hexStringToBuffer(packet);
  };
};

exports.adapter = adapter;